---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Payment form: Card details with live formatting, brand detection and a clear total.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change payment-form.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './payment-form.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="payment-form" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="pyx-wrap"><form class="pyx panel" novalidate>
  <div class="pyx-h"><div><b>Pro plan</b><span class="muted">For growing design teams</span></div><div class="seg2 pyx-per" role="group" aria-label="Billing"><button type="button" aria-pressed="false" data-v="m">Monthly</button><button type="button" aria-pressed="true" data-v="y">Yearly</button></div></div>
  <label class="pyx-f"><span>Card number</span><div class="pyx-in"><input class="pyx-cn" inputmode="numeric" placeholder="1234 1234 1234 1234" autocomplete="off"><span class="pyx-br"></span></div></label>
  <div class="pyx-2"><label class="pyx-f"><span>Expiry</span><div class="pyx-in"><input class="pyx-ex" inputmode="numeric" placeholder="MM / YY" autocomplete="off"></div></label><label class="pyx-f"><span>CVC</span><div class="pyx-in"><input class="pyx-cv" inputmode="numeric" placeholder="123" maxlength="4" autocomplete="off"></div></label></div>
  <div class="pyx-sum"><div><span>3 editors × <span class="num pyx-u">$24</span></span><span class="num pyx-s">$72.00</span></div><div class="pyx-dc"><span>Yearly discount</span><span class="num pyx-d">−$14.40</span></div><div class="pyx-t"><b>Due today</b><b class="num pyx-tot">$691.20</b></div></div>
  <button class="pill accent pyx-go" type="submit"><svg class="i xs"><use href="#i-lock"/></svg>Pay <span class="num pyx-gt">$691.20</span></button>
</form>
  <span class="muted pyx-n pyx-out">Demo only. Nothing is charged.</span></div>
  </Fragment></div>
</div>
<script>
  import './payment-form.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Payment form ---------- */
.pyx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);max-width:360px;margin:0 auto;width:100%}
.pyx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}
.pyx-h>div:first-child{display:flex;flex-direction:column;font-size:14px}
.pyx-h b{font-weight:500}
.pyx-h .muted{font-size:12px}
.pyx-per button{font-size:12px;height:26px;padding:0 9px}
/* the card's fields have no box: the text lines up with its label, with room above and below it, over a dimmed line that
   steps up while the field has the focus. Left, a filled field looks like an empty one */
.pyx-f{display:flex;flex-direction:column;gap:6px;font-size:12.5px;font-weight:500;min-width:0}
/* each field is a full outline like every other field: a dimmed grey edge, empty or filled, one step stronger only while it
   has the focus */
.pyx-in{display:flex;align-items:center;gap:var(--dm-s-2);height:var(--dm-field-h);padding:0 var(--dm-s-2) 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.pyx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.pyx-in:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* a field marked wrong keeps its red line, focused or not, until it is fixed */
.pyx-f.bad .pyx-in{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.pyx-in input{flex:1;min-width:0;height:100%;padding:0;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;font-weight:400;font-variant-numeric:tabular-nums;color:var(--dm-fg)}
.pyx-in input::placeholder{color:var(--dm-muted)}
.pyx-br{font-size:10px;font-weight:500;letter-spacing:.04em;padding:3px 6px;border-radius:var(--dm-r-xs);opacity:0;transform:scale(.8);transition:opacity .3s,transform .35s var(--dm-ease)}
.pyx-br.on{opacity:1;transform:none}
.pyx-2{display:grid;grid-template-columns:1fr 1fr;gap:var(--dm-s-3)}
/* the details: plain rows after a line, no panel */
.pyx-sum{display:flex;flex-direction:column;gap:6px;margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;color:var(--dm-fg2)}
.pyx-sum>div{display:flex;justify-content:space-between}
.pyx-dc{color:var(--dm-ok);transition:opacity .3s}
.pyx-dc.off{opacity:.3;text-decoration:line-through}
.pyx-t{padding-top:6px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg);font-size:13.5px}
.pyx-t b{font-weight:500}
.pyx-go{height:var(--dm-field-h);width:100%}
.pyx-go.ok{background:var(--dm-ok)}
.pyx-n{font-size:11.5px;text-align:center}
/* on the site the form stands alone, with the demo line under it, outside the form */
.pyx-wrap{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-3);width:100%;max-width:360px;margin:0 auto}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, enter, seg, tween } from '../core/core.js';
DM.def('payment-form', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{lock}', I('lock','xs'));
  const cn = $('.pyx-cn', r), ex = $('.pyx-ex', r), cv = $('.pyx-cv', r), br = $('.pyx-br', r);
  const BR = [[/^4/, 'VISA', '#1a1f71'], [/^5[1-5]/, 'MC', '#eb001b'], [/^3[47]/, 'AMEX', '#2e77bb']];
  cn.oninput = demo => { const d = cn.value.replace(/\D/g, '').slice(0, 16); cn.value = d.replace(/(.{4})/g, '$1 ').trim(); const b = BR.find(x => x[0].test(d));
    br.classList.toggle('on', !!b); if (b){ br.textContent = b[1]; br.style.background = b[2]; br.style.color = '#fff'; } cn.closest('.pyx-f').classList.remove('bad'); if (d.length === 16 && demo !== true) ex.focus({ preventScroll:true }); };
  ex.oninput = () => { let d = ex.value.replace(/\D/g, '').slice(0, 4); if (d.length === 1 && +d > 1) d = '0' + d; ex.value = d.length > 2 ? d.slice(0, 2) + ' / ' + d.slice(2) : d; ex.closest('.pyx-f').classList.remove('bad'); if (d.length === 4) cv.focus({ preventScroll:true }); };
  cv.oninput = () => { cv.value = cv.value.replace(/\D/g, ''); cv.closest('.pyx-f').classList.remove('bad'); };
  let per = 'y', tot = 691.2;
  function price(){ const unit = 24, sub = unit * 3, yr = per === 'y'; const t = yr ? sub * 12 * .8 : sub;
    $('.pyx-s', r).textContent = '$' + (yr ? sub * 12 : sub).toFixed(2); $('.pyx-d', r).textContent = yr ? '−$' + (sub * 12 * .2).toFixed(2) : '−$0.00'; $('.pyx-dc', r).classList.toggle('off', !yr);
    $('.pyx-u', r).textContent = yr ? '$24 × 12' : '$24';
    tween(tot, t, 600, v => { tot = v; $('.pyx-tot', r).textContent = '$' + v.toFixed(2); $('.pyx-gt', r).textContent = '$' + v.toFixed(2); }); }
  seg($('.pyx-per', r), v => { per = v; price(); });
  price();
  $('.pyx', r).onsubmit = e => { e.preventDefault(); let ok = true;
    [[cn, cn.value.replace(/\D/g, '').length === 16], [ex, /^\d\d \/ \d\d$/.test(ex.value)], [cv, cv.value.length >= 3]].forEach(([el, good]) => { if (!good){ ok = false; const f = el.closest('.pyx-f'); f.classList.remove('bad'); void f.offsetWidth; f.classList.add('bad'); } });
    if (!ok) return;
    c.run(async () => { const go = $('.pyx-go', r); go.innerHTML = '<span class="spin" style="border-color:rgba(255,255,255,.3);border-top-color:#fff"></span>Processing'; await c.wait(1200); go.classList.add('ok'); go.innerHTML = I('check','xs') + 'Payment successful'; enter(go.firstChild); }); };
  // the preview types a test card on its own; clicking, focusing or typing in it takes over, and what it had typed goes
  c.auto(1000, () => c.run(() => c.type(cn, '4242424242424242', { ms:45, each:() => cn.oninput(true) })));
});
